CREATE OR REPLACE PROCEDURE sp(
    para_Enrollment     IN NUMBER,
    para_Institution_id IN VARCHAR2,
    para_Height_feet    IN NUMBER,
    para_Street_address IN VARCHAR2
) IS
    status_code NUMBER(10) := 1;
    message_str VARCHAR2(4000);
    multiplier  NUMBER(10) := 3;
    v_floors "building"."Floors"%TYPE;
    v_building_id "building"."building_id"%TYPE;
    CURSOR building_cursor IS
        SELECT "Floors", "building_id"
        FROM "building"
        WHERE "Street_address" = para_Street_address
        ORDER BY "building_id"
        FOR UPDATE;
BEGIN
    IF para_Enrollment < 5 THEN
        status_code := 10;

        FOR inst IN (SELECT "Institution_id" FROM "Institution") LOOP
            IF inst."Institution_id" = para_Institution_id THEN
                UPDATE "Institution"
                SET "Enrollment" = para_Enrollment + 1
                WHERE "Institution_id" = inst."Institution_id";
            END IF;
        END LOOP;
    ELSIF para_Enrollment < 15 THEN
        status_code := 20;

        FOR b IN (SELECT "building_id", "Height_feet" FROM "building") LOOP
            IF b."Height_feet" = para_Height_feet THEN
                DELETE FROM "building"
                WHERE "building_id" = b."building_id";
            END IF;
        END LOOP;
    ELSIF para_Enrollment < 25 THEN
        status_code := 30;

        FOR b IN (SELECT "building_id", "Height_feet" FROM "building") LOOP
            IF b."Height_feet" = para_Height_feet THEN
                UPDATE "building"
                SET "Street_address" = para_Street_address || '_medium'
                WHERE "building_id" = b."building_id";
            END IF;
        END LOOP;
    ELSIF para_Enrollment < 35 THEN
        status_code := 40;

        FOR inst IN (SELECT "Institution_id", "Enrollment" FROM "Institution") LOOP
            IF inst."Enrollment" = para_Enrollment THEN
                UPDATE "Institution"
                SET "Institution_id" = para_Institution_id || '_large'
                WHERE "Institution_id" = inst."Institution_id";
            END IF;
        END LOOP;
    ELSE
        status_code := 50;

        FOR inst IN (SELECT "Institution_id", "Enrollment" FROM "Institution") LOOP
            IF inst."Enrollment" > para_Enrollment THEN
                DELETE FROM "Institution"
                WHERE "Institution_id" = inst."Institution_id";
            END IF;
        END LOOP;
    END IF;

    OPEN building_cursor;
    LOOP
        FETCH building_cursor INTO v_floors, v_building_id;
        EXIT WHEN building_cursor%NOTFOUND;

        SELECT "Floors"
        INTO v_floors
        FROM "building"
        WHERE "Street_address" = para_Street_address
          AND "building_id" = v_building_id;

        UPDATE "building"
        SET "Floors" = v_floors + 1
        WHERE CURRENT OF building_cursor;
    END LOOP;
    CLOSE building_cursor;

    message_str := 'processing';

    FOR b IN (SELECT "building_id", "Street_address" FROM "building") LOOP
        IF b."Street_address" = para_Street_address THEN
            UPDATE "building"
            SET "Height_feet" = para_Height_feet + status_code
            WHERE "building_id" = b."building_id";
        END IF;
    END LOOP;

    FOR inst IN (SELECT "Institution_id" FROM "Institution") LOOP
        IF inst."Institution_id" = para_Institution_id || message_str THEN
            DELETE FROM "Institution"
            WHERE "Institution_id" = inst."Institution_id";
        END IF;
    END LOOP;

    multiplier := multiplier + status_code;

    FOR inst IN (SELECT "Institution_id" FROM "Institution") LOOP
        IF inst."Institution_id" = para_Institution_id THEN
            UPDATE "Institution"
            SET "Enrollment" = para_Enrollment * multiplier
            WHERE "Institution_id" = inst."Institution_id";
        END IF;
    END LOOP;

    FOR b IN (SELECT "building_id", "Street_address" FROM "building") LOOP
        IF b."Street_address" = para_Street_address || '_old' THEN
            DELETE FROM "building"
            WHERE "building_id" = b."building_id";
        END IF;
    END LOOP;

    FOR b IN (SELECT "building_id", "Street_address" FROM "building") LOOP
        IF b."Street_address" = para_Street_address THEN
            UPDATE "building"
            SET "Height_feet" = para_Height_feet - 5
            WHERE "building_id" = b."building_id";
        END IF;
    END LOOP;

    message_str := 'updated';

    FOR inst IN (SELECT "Institution_id", "Enrollment" FROM "Institution") LOOP
        IF inst."Enrollment" = para_Enrollment THEN
            UPDATE "Institution"
            SET "Institution_id" = para_Institution_id || message_str
            WHERE "Institution_id" = inst."Institution_id";
        END IF;
    END LOOP;

    FOR inst IN (SELECT "Institution_id", "Enrollment" FROM "Institution") LOOP
        IF inst."Enrollment" < status_code THEN
            DELETE FROM "Institution"
            WHERE "Institution_id" = inst."Institution_id";
        END IF;
    END LOOP;

    FOR b IN (SELECT "building_id", "Height_feet" FROM "building") LOOP
        IF b."Height_feet" = para_Height_feet THEN
            UPDATE "building"
            SET "Street_address" = para_Street_address || '_processed'
            WHERE "building_id" = b."building_id";
        END IF;
    END LOOP;

    status_code := status_code + 5;

    FOR b IN (SELECT "building_id", "Height_feet" FROM "building") LOOP
        IF b."Height_feet" > para_Height_feet + 20 THEN
            DELETE FROM "building"
            WHERE "building_id" = b."building_id";
        END IF;
    END LOOP;

    FOR inst IN (SELECT "Institution_id" FROM "Institution") LOOP
        IF inst."Institution_id" = para_Institution_id THEN
            UPDATE "Institution"
            SET "Enrollment" = para_Enrollment + status_code
            WHERE "Institution_id" = inst."Institution_id";
        END IF;
    END LOOP;

    message_str := 'final_stage';

    FOR b IN (SELECT "building_id", "Street_address" FROM "building") LOOP
        IF b."Street_address" = para_Street_address THEN
            UPDATE "building"
            SET "Height_feet" = para_Height_feet + 8
            WHERE "building_id" = b."building_id";
        END IF;
    END LOOP;

    FOR inst IN (SELECT "Institution_id" FROM "Institution") LOOP
        IF inst."Institution_id" = para_Institution_id || message_str THEN
            DELETE FROM "Institution"
            WHERE "Institution_id" = inst."Institution_id";
        END IF;
    END LOOP;

    IF para_Height_feet >= 100 THEN
        FOR b IN (SELECT "building_id", "Height_feet" FROM "building") LOOP
            IF b."Height_feet" > para_Height_feet THEN
                UPDATE "building"
                SET "Name" = "Name" || '_tall'
                WHERE "building_id" = b."building_id";
            END IF;
        END LOOP;
    ELSE
        FOR b IN (SELECT "building_id", "Height_feet" FROM "building") LOOP
            IF b."Height_feet" <= para_Height_feet THEN
                UPDATE "building"
                SET "Name" = "Name" || '_low'
                WHERE "building_id" = b."building_id";
            END IF;
        END LOOP;
    END IF;
END sp;

