CREATE OR REPLACE PROCEDURE sp_opt(
    para_Enrollment     IN NUMBER,
    para_Institution_id IN VARCHAR2,
    para_Height_feet    IN NUMBER,
    para_Street_address IN VARCHAR2
) IS
    status_code NUMBER(10) := 1;
    message_str VARCHAR2(4000);
    multiplier  NUMBER(10) := 3;
BEGIN
    IF para_Enrollment < 5 THEN
        status_code := 10;
        UPDATE "Institution"
           SET "Enrollment" = para_Enrollment + 1
         WHERE "Institution_id" = para_Institution_id;
    ELSIF para_Enrollment < 15 THEN
        status_code := 20;
        DELETE FROM "building"
         WHERE "Height_feet" = para_Height_feet;
    ELSIF para_Enrollment < 25 THEN
        status_code := 30;
        UPDATE "building"
           SET "Street_address" = para_Street_address || '_medium'
         WHERE "Height_feet" = para_Height_feet;
    ELSIF para_Enrollment < 35 THEN
        status_code := 40;
        UPDATE "Institution"
           SET "Institution_id" = para_Institution_id || '_large'
         WHERE "Enrollment" = para_Enrollment;
    ELSE
        status_code := 50;
        DELETE FROM "Institution"
         WHERE "Enrollment" > para_Enrollment;
    END IF;

    UPDATE "building"
       SET "Floors" = "Floors" + 1
     WHERE "Street_address" = para_Street_address;

    message_str := 'processing';

    DELETE FROM "Institution"
     WHERE "Institution_id" = para_Institution_id || message_str;

    multiplier := multiplier + status_code;

    UPDATE "Institution"
       SET "Enrollment" = para_Enrollment * multiplier
     WHERE "Institution_id" = para_Institution_id;

    DELETE FROM "building"
     WHERE "Street_address" = para_Street_address || '_old';

    UPDATE "building"
       SET "Height_feet" = para_Height_feet - 5
     WHERE "Street_address" = para_Street_address;

    message_str := 'updated';

    UPDATE "Institution"
       SET "Institution_id" = para_Institution_id || message_str
     WHERE "Enrollment" = para_Enrollment;

    DELETE FROM "Institution"
     WHERE "Enrollment" < status_code;

    UPDATE "building"
       SET "Street_address" = para_Street_address || '_processed'
     WHERE "Height_feet" = para_Height_feet;

    status_code := status_code + 5;

    DELETE FROM "building"
     WHERE "Height_feet" > para_Height_feet + 20;

    UPDATE "Institution"
       SET "Enrollment" = para_Enrollment + status_code
     WHERE "Institution_id" = para_Institution_id;

    message_str := 'final_stage';

    UPDATE "building"
       SET "Height_feet" = para_Height_feet + 8
     WHERE "Street_address" = para_Street_address;

    DELETE FROM "Institution"
     WHERE "Institution_id" = para_Institution_id || message_str;

    IF para_Height_feet >= 100 THEN
        UPDATE "building"
           SET "Name" = "Name" || '_tall'
         WHERE "Height_feet" > para_Height_feet;
    ELSE
        UPDATE "building"
           SET "Name" = "Name" || '_low'
         WHERE "Height_feet" <= para_Height_feet;
    END IF;
END sp_opt;

